 if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){if(!hash_equals((string)$_SESSION['meeting_followup_csrf'],(string)($_POST['_csrf']??'')))throw new RuntimeException('Session expirée. Rechargez la page.');$mode=(string)($_POST['mode']??'complete');$answers=json_decode((string)($_POST['answers']??'{}'),true);if(!is_array($answers))throw new RuntimeException('Réponses invalides.');if($mode==='bulk_defer'){$date=(string)($_POST['defer_date']??'');$note=(string)($_POST['note']??'');foreach($service->pendingForUser($uid,$now) as $item)$answers[(int)$item['checklist_id']]=['type'=>'decision_deferred','date'=>$date,'note'=>$note];}echo json_encode(['success'=>true]+$service->submit($uid,$answers,$now,$mode==='partial'),JSON_UNESCAPED_UNICODE);exit;}
